{
  "@context": {
    "@language": "en",
    "@vocab": "https://schema.org/",
    "cr": "http://mlcommons.org/croissant/",
    "dct": "http://purl.org/dc/terms/",
    "sc": "https://schema.org/"
  },
  "@type": "cr:TaskProblem",
  "conformsTo": "http://mlcommons.org/croissant/1.0",
  "@id": "airfoil-design-optimization-task",
  "name": "Airfoil Design Optimization via ML-Based Surrogate Models",
  "description": "Develop machine learning models to simulate computational fluid dynamics (CFD) for airfoil design, replacing computationally expensive numerical methods. The goal is to predict physical simulation outputs (e.g., velocity, pressure, lift, drag) based on input geometries and boundary conditions, while optimizing computational efficiency, accuracy, and physical consistency.",
  "paper_id": "[FILL IN THE BLANK: paper identifier]",

  "cr:input": [
    {
      "@type": "cr:FileObject",
      "name": "AirfRANS dataset",
      "description": "Unstructured mesh data representing 2D simulation domains. Includes positions (x, y coordinates of mesh nodes), inlet velocity (scalar, e.g., 10 m/s), distance to the airfoil (scalar), normals (vector values representing surface orientation), and boundary conditions (e.g., angle of attack, Reynolds number).",
      "encodingFormat": "[FILL IN THE BLANK: dataset file format, e.g., text/csv, application/json]",
      "contentUrl": "[FILL IN THE BLANK: dataset download URL]"
    }
  ],

  "cr:output": {
    "name": "predictions",
    "description": "Predictions for velocity components (u_x, u_y), pressure divided by specific mass (p_s), turbulent kinematic viscosity (nu_t), and derived quantities (lift coefficient C_L, drag coefficient C_D).",
    "cr:schema": {
      "@type": "cr:RecordSet",
      "name": "prediction_schema",
      "field": [
        {
          "@type": "cr:Field",
          "name": "u_x",
          "dataType": "sc:Float",
          "description": "Velocity component in the x direction. Example: 0.5."
        },
        {
          "@type": "cr:Field",
          "name": "u_y",
          "dataType": "sc:Float",
          "description": "Velocity component in the y direction. Example: -0.3."
        },
        {
          "@type": "cr:Field",
          "name": "p_s",
          "dataType": "sc:Float",
          "description": "Pressure divided by specific mass. Example: 101325."
        },
        {
          "@type": "cr:Field",
          "name": "nu_t",
          "dataType": "sc:Float",
          "description": "Turbulent kinematic viscosity. Example: 1.5e-5."
        },
        {
          "@type": "cr:Field",
          "name": "C_L",
          "dataType": "sc:Float",
          "description": "Lift coefficient. Example: 1.2."
        },
        {
          "@type": "cr:Field",
          "name": "C_D",
          "dataType": "sc:Float",
          "description": "Drag coefficient. Example: 0.03."
        }
      ]
    }
  },

  "cr:implementation": {
    "cr:environment": {
      "language": "Python",
      "packages": ["TensorFlow", "PyTorch", "[FILL IN THE BLANK: other required packages]"]
    },
    "entryPoint": "solution.py",
    "interface": "predict(input_dir, output_dir)"
  },

  "cr:evaluation": {
    "primaryMetric": "Global Score",
    "metrics": [
      "Mean Squared Error (MSE)",
      "Speedup (logarithmic scale)",
      "Spearman correlation (rho_D, rho_L)",
      "Mean Relative Error (C_D, C_L)"
    ],
    "higherIsBetter": true,
    "notes": "Global Score is a weighted combination of ML-related metrics (40%), physics compliance (30%), and OOD generalization (30%). Metrics are scored based on thresholds (e.g., T1, T2) for unacceptable, acceptable, and great results."
  },

  "cr:execution": {
    "runtimeLimitSec": 259200,
    "memoryLimitMb": 4096,
    "allowedExternalData": "unknown"
  },

  "open_questions": [
    "What is the exact dataset download URL?",
    "What is the exact file format of the dataset (e.g., text/csv, application/json)?",
    "What are the exact package versions required for TensorFlow, PyTorch, and other dependencies?",
    "Are participants allowed to use external data for training?"
  ],

  "fill_in_the_blank": [
    "paper_id - reason it could not be determined from the paper",
    "cr:input[0].encodingFormat - reason it could not be determined from the paper",
    "cr:input[0].contentUrl - reason it could not be determined from the paper",
    "cr:implementation.cr:environment.packages[2] - reason it could not be determined from the paper"
  ]
}
